HTML='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Turing | Anthropic workflow diagnostic</title>
<style>:root{--ink:#1c272d;--muted:#5d686c;--paper:#f4f1e9;--white:#fffdf8;--line:#d8d6cb;--green:#1d5e51;--rust:#943e24}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:17px/1.55 system-ui,sans-serif}main{max-width:1120px;margin:auto;padding:32px 28px 80px}header{display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap;color:var(--muted);font-size:13px;letter-spacing:.08em;text-transform:uppercase}.hero{padding:44px 0 30px;border-bottom:1px solid var(--line)}.eyebrow{color:var(--green);font-size:13px;font-weight:700;letter-spacing:.08em;text-transform:uppercase}h1{font:normal clamp(38px,6vw,70px)/1.03 Georgia,serif;letter-spacing:-.035em;max-width:850px;margin:14px 0 24px}h2{font:normal 34px/1.15 Georgia,serif;margin:42px 0 16px}h3{font-size:20px;margin:0 0 10px}.lead{font-size:21px;max-width:850px}.ask{max-width:850px;border-left:4px solid var(--green);padding-left:18px}.links,.tabs,.stats{display:flex;gap:12px;flex-wrap:wrap}.links{margin:24px 0}a{color:var(--green);text-underline-offset:3px}.button,button{display:inline-block;border:1px solid var(--green);border-radius:4px;padding:11px 16px;font:600 14px system-ui;text-decoration:none;color:white;background:var(--green);cursor:pointer}.secondary{background:transparent;color:var(--green)}.stats{margin:28px 0 0;gap:0}.stat{flex:1;min-width:160px;border-left:1px solid var(--line);padding:4px 20px}.stat:first-child{border-left:0;padding-left:0}.stat strong{display:block;font-size:32px;font-weight:500}.stat span{font-size:13px;color:var(--muted)}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.case{background:var(--white);border:1px solid var(--line);padding:24px}.label{font-size:12px;text-transform:uppercase;letter-spacing:.06em;color:var(--muted)}blockquote{border-left:3px solid var(--rust);margin:16px 0;padding-left:16px;font:22px/1.4 Georgia,serif}.tag{display:inline-block;background:#e4eee4;border-radius:3px;padding:4px 8px;font-size:12px;color:var(--green)}.muted{font-size:14px;color:var(--muted)}.notice{border:1px solid #c9b99d;border-left:4px solid var(--rust);padding:17px 20px;background:#fff8ed}table{width:100%;border-collapse:collapse;font-size:14px;background:var(--white)}th,td{padding:13px 14px;text-align:left;border-bottom:1px solid var(--line);vertical-align:top}th{font-size:12px;color:var(--muted);text-transform:uppercase;letter-spacing:.04em}.tablewrap{overflow-x:auto}details{border-bottom:1px solid var(--line);padding:15px 0}summary{font-weight:600;cursor:pointer}.pitch{background:var(--white);border:1px solid var(--line);padding:28px;margin-top:14px}.tabs button[aria-selected=false]{background:transparent;color:var(--green)}.pitch blockquote{font-size:24px}.split{display:flex;gap:2px;margin:16px 0}.split span{padding:14px;text-align:center;background:#dce8df;font-size:14px}.split span:last-child{background:#c7d7de}input{font:inherit;max-width:100%;padding:7px;border:1px solid #b7c1c5;border-radius:3px}label{display:block;font-size:14px;margin:10px 0}label input{display:block;width:100%;margin-top:5px}.cost{background:#e6eee8;padding:20px}.cost output{font-size:30px;display:block}footer{border-top:1px solid var(--line);margin-top:40px;padding-top:20px;font-size:13px;color:var(--muted)}:focus-visible{outline:3px solid #c18a2c;outline-offset:4px}[hidden]{display:none!important}@media(max-width:700px){main{padding:24px 18px 50px}.grid{grid-template-columns:1fr}.hero{padding-top:28px}.stat{min-width:45%;margin-bottom:15px}.lead{font-size:19px}table{min-width:570px}.pitch{padding:20px}h2{font-size:29px}}</style></head><body><main>
<header><span>Turing · Field Engineer take-home</span><span>31 October 2026 · Private working evidence</span></header>
<section class="hero"><div class="eyebrow">Anthropic discussion / Workflow evaluation</div><h1>Correct facts can still hide a broken plan.</h1><p class="lead">Can the agent preserve authority and uncertainty in the final deliverable while completing authorized work? Two purchasing examples make the question concrete; the next step is calibrated human review.</p><p class="ask"><strong>The offer:</strong> a private, permissioned 30-family workflow diagnostic with source files, native expert deliverables, rubrics and preference rationales. Test tools and prompts before investing in training data.</p><div class="links"><a class="button" href="../output/pdf/turing-anthropic-pitch.pdf">Anthropic pitch + decision metrics</a><a class="button secondary" href="../output/pdf/turing-submission-one-page.pdf">One-page submission</a><a class="button secondary" href="../output/pdf/turing-panel-review-and-pitches.pdf">Panel review + two pitches</a><a class="button secondary" href="review/index.html?queue=purchasing">Review purchasing cases</a><a class="button secondary" href="../output/pdf/turing-anthropic-evidence-defense.pdf">Transcripts + grader defenses</a></div><div class="stats"><div class="stat"><strong>5</strong><span>source families in the main study</span></div><div class="stat"><strong>60</strong><span>main-study attempts, not independent tasks</span></div><div class="stat"><strong>2</strong><span>owner judgments on specific issues</span></div><div class="stat"><strong>$5.17</strong><span>all API spending, including the later probe</span></div></div></section>
<section><h2>Two operational contradictions</h2><div class="grid"><article class="case"><div class="label">Supplier continuity</div><h3>Unknown inventory becomes assured coverage</h3><p>The approved cutoff is 21 days. Replacement takes months. Opening stock is unknown.</p><blockquote>“Absent an agreement, buffer stock and air freight cover the gap.”</blockquote><p>The same document admits production may be interrupted. Its action table should preserve that uncertainty.</p><span class="tag">Owner: material correction required</span><p class="muted">Claude recovery, repeat 2 · issue severity only.</p><a href="../reviews/purchasing_calibration/case-A-full-output.pdf">Complete output</a></article><article class="case"><div class="label">Sourcing approval</div><h3>An exception weakens the stated rule</h3><p>The approved rule requires Finance, Program and Purchase. The output knows this.</p><blockquote>“This must be recorded and approved by the Program Manager and Purchase.”</blockquote><p>The provisional-release clause names two approvers; nearby text restores all three. Its draft status and caveats matter.</p><span class="tag">Owner: material correction required</span><p class="muted">Claude conflict, repeat 1 · issue severity only.</p><a href="../reviews/purchasing_calibration/case-B-full-output.pdf">Complete output</a></article></div><p class="muted">Both are Claude outputs. No OpenAI-specific substantive failure is human-calibrated. Two selected issue labels do not establish whole-output acceptance, expert qualification or a population error rate.</p></section>
<section><h2>What the measurements actually say</h2><div class="tablewrap"><table><thead><tr><th>Own-run evidence</th><th>Count</th><th>Interpretation</th></tr></thead><tbody><tr><td>Valid output + targeted audit facts</td><td>53 / 60</td><td>All parseable outputs stated the tested facts correctly. This misses contradictory document prose.</td></tr><tr><td>Output failures</td><td>7 / 60</td><td>Five hit the 6,500-token cap. Budget and serialization controls come first.</td></tr><tr><td>Bounded documents over the page limit</td><td>18 / 35</td><td>Fixed renderer; models could not inspect and revise native pages.</td></tr><tr><td>Exported shipment workbook checks</td><td>12 / 12</td><td>Value checks passed; human acceptance is unmeasured.</td></tr><tr><td>Model-judge critical-label agreement</td><td>10 / 12</td><td>All ten agreements were negative; zero shared positives. This is not human calibration.</td></tr></tbody></table></div><p class="notice"><strong>The 16-run repair probe is diagnostic only.</strong> It had 15 valid fact-check passes and five native-document/page passes, with no aggregate artifact improvement. All 16 inputs contained contradictory dates. Corrected candidates are unrun. Four earlier EV-conflict attempts also have a task defect.</p><details><summary>Setup, sample and uncertainty</summary><p>Five public families across purchasing (3), project management (1) and shipping (1), selected for inspectable documents and calculations. Two models, three conditions and two repeats. Variants share ancestry. The solver received text/table extracts, record-reading tools and a JSON artifact schema. DOCX/XLSX were exported afterward. No PPTX task ran. These are not official GDPval scores.</p><p>The historical 21/56 provisional acceptance figure is model-judged. A new audit disputes missing-tracker grades: the runner requested two Word files while a reference asked for an Excel tracker. Historical scores remain preserved, not promoted to expert acceptance. Counts are descriptive; five selected families cannot support broad reliability claims.</p></details><details><summary>Provenance, seeds and contamination</summary><p>GDPval source revision 11e7900. Local deterministic transformations supplied missing/conflicting records. No teacher API generated business facts; seeds randomized run order only. No training was performed. All current families and descendants are excluded from later training. Public pretraining exposure is unknown; public availability does not itself prove contamination. Commercial permissions remain unverified.</p></details></section>
<section><h2>A taxonomy ready for your review</h2><p>35 historically flagged attempts, seven mutually exclusive primary categories. These are <strong>provisional engineering assignments</strong>, not 35 human-confirmed model failures. The largest category concerns setup and grading.</p><div class="tablewrap"><table><thead><tr><th>Primary category</th><th>Attempts</th><th>Severity / first response</th></tr></thead><tbody>__TAXONOMY__</tbody></table></div><details><summary>Counting rules and six raw transcripts</summary><p>Contract defects take priority, followed by invalid serialization, approval errors, unsupported continuity, unsupported eligibility, incomplete comparisons and page overflow. Five token-cap failures sit inside the contract category, not in a second count.</p>__TRACES__<p class="muted">The first three support the largest setup category. The last three show business-error candidates; only the first supplier example has the earlier owner judgment. Native files and observable tool traces are included.</p></details><div class="links"><a class="button" href="review/index.html">20-output calibration queue</a><a class="button secondary" href="review/index.html?queue=failure">35-attempt taxonomy queue</a></div><p class="muted">43 distinct attempts across the queues. Review calibration first. No full-output human labels are completed; prior issue judgments remain separate. Export JSON when finished.</p></section>
<section><h2>The Anthropic conversation</h2><div class="tabs" role="tablist" aria-label="Researcher perspective"><button id="anthropic-tab" role="tab" aria-selected="true" aria-controls="anthropic-pitch">Anthropic · primary pitch</button><button id="openai-tab" role="tab" aria-selected="false" aria-controls="openai-pitch">OpenAI · alternative</button></div><article class="pitch" id="openai-pitch" role="tabpanel" aria-labelledby="openai-tab" hidden><div class="eyebrow">Residual supervision after tools and compute</div><h3>Which failures survive a capable tool loop?</h3><blockquote>“We found a supervision gap worth testing—not a verified deficit in your model. Test fresh professional episodes on your own stack before buying training data.”</blockquote><p>Show correct audit facts next to an inconsistent artifact. Separate this from five output-cap failures. Offer 30 permissioned families with native expert outputs, scalable checks, preference pairs and evidence rationales.</p><p><strong>RL signal:</strong> authorized, source-consistent completed work. Opening a file or copying a fact does not earn success. Use separate training lineages only if human-confirmed failures survive prompt, state-tool and native-file controls.</p><p><strong>Hardest question:</strong> “Which OpenAI failure remains after more budget and render-and-revise tools?”<br><strong>Current answer:</strong> none is human-calibrated as a residual semantic deficit here.</p></article><article class="pitch" id="anthropic-pitch" role="tabpanel" aria-labelledby="anthropic-tab"><div class="eyebrow">Authority, uncertainty and useful action</div><h3>Does the final plan preserve the governing constraint?</h3><blockquote>“The agent found the approved rule, then weakened it in an exception. Test that failure alongside cases where the correct behavior is to proceed.”</blockquote><p>Show the whole clause and its caveats. Distinguish an actionable bypass from a proposal awaiting approval. Do not call an inconsistency intentional deception. Include justified holds and authorized actions so excessive refusal cannot win.</p><p><strong>The buying decision:</strong> first establish expert acceptance and consequential errors; also measure authorized completion and unnecessary holds. Compare paired variants at the family level. Select the lowest total cost per accepted deliverable only after the agreed error and utility gates pass. No configuration qualifies on the current evidence.</p><p><strong>Validation:</strong> ten judge agreements were all negatives. The GPT judge flagged ten Claude outputs and no GPT outputs; bias and true quality differences remain unresolved.</p><p><strong>Hardest question:</strong> “Will another reviewer reproduce this taxonomy?”<br><strong>Current answer:</strong> unknown. Double-code a fixed sample, report the confusion matrix and adjudicate disagreement.</p></article><p class="muted">Two independent AI assessments of the earlier submission, not human reviews or lab endorsements: <a href="../output/panel_review/openai_review.json">OpenAI-perspective notes</a> · <a href="../output/panel_review/anthropic_review.json">Anthropic-perspective notes</a>.</p></section>
<section><h2>The product to buy first</h2><p><strong>30 fresh purchasing families.</strong> Stable objectives, three workflow versions, permissioned source files, authority/dependency state, native gold deliverables, scalable rubrics, at least two expert preference pairs per family and source-grounded rationales.</p><div class="split"><span style="flex:10">10 development families</span><span style="flex:20">20 untouched evaluation families</span></div><p>No training in this pilot. Conditional expansion: 240 further families across three occupations, split 120 training / 60 development / 60 sealed test by source and template ancestry. Three versions make 720 instances, not 720 independent tasks.</p><details><summary>Acceptance and refresh gates</summary><p>Verify rights, realism, solvability, chronology and a consistent deliverable contract. Two qualified reviewers validate consequential labels and preferences. Test outputs with correct audit fields but contradictory actions, and positive controls where action is authorized.</p><p>Select by total cost per accepted deliverable only among configurations meeting agreed error and acceptance thresholds. Include all attempts and actual human minutes. Proposed cadence: monthly drift/rights checks and quarterly new lineages or after material workflow changes. No inspected evaluation descendants enter training.</p></details><div class="grid"><div><h3>Illustrative production cost</h3><p>Planning inputs, not measured rates, a quote or spending authorization. The $25 cap covers our API experiment only.</p><div class="grid"><label>Expert hours per family<input id="hours" type="number" min="0" step="0.25" value="3.5"></label><label>Expert hourly rate, USD<input id="rate" type="number" min="0" value="100"></label><label>API cost per family, USD<input id="api" type="number" min="0" step="0.5" value="2"></label><label>Accepted-family yield, %<input id="yield" type="number" min="1" max="100" value="90"></label></div></div><div class="cost"><span>Cost per accepted family</span><output id="unitCost"></output><p id="pilotCost"></p><p class="muted">(Hours × hourly rate + API cost) ÷ yield. Actual expert labor is unmeasured; no customer ROI is claimed.</p></div></div></section>
<section><h2>Evidence and next action</h2><p><strong>Complete human calibration, then resolve task validity.</strong> The coding, packaging and AI review are ready. Your own inspection is the part an agent cannot truthfully claim on your behalf.</p><div class="links"><a class="button" href="review/index.html">Start the review</a><a class="button secondary" href="../output/turing-panel-submission-kit.zip">Private evidence + code package</a></div><p><a href="../output/submission_audit/summary.json">Audit counts</a> · <a href="../output/submission_audit/grader_diagnostics.json">Judge confusion matrix</a> · <a href="../output/submission_audit/setup_audit.json">Setup audit</a> · <a href="../output/paired_v1/summary.json">Original results</a> · <a href="../output/repair_probe_01/task_defects.json">Probe defects</a></p></section>
<footer>Framework: <a href="https://arxiv.org/html/2510.04374v1">GDPval</a> and its <a href="https://huggingface.co/datasets/openai/gdpval">official public release</a>. Reporting: <a href="https://arxiv.org/html/2606.09809v2">Evaluation Cards</a>. Performance counts come from local logs, not paper leaderboards. Documentation does not establish superiority. These local working files have not been submitted or published.</footer>
</main><script>for(const lab of ['openai','anthropic'])document.getElementById(lab+'-tab').onclick=()=>{for(const x of ['openai','anthropic']){document.getElementById(x+'-tab').setAttribute('aria-selected',String(x===lab));document.getElementById(x+'-pitch').hidden=x!==lab}};function cost(){const v=Object.fromEntries(['hours','rate','api','yield'].map(k=>[k,Number(document.getElementById(k).value)]));const valid=Object.values(v).every(Number.isFinite)&&v.hours>=0&&v.rate>=0&&v.api>=0&&v.yield>0&&v.yield<=100;if(!valid){document.getElementById('unitCost').textContent='Check inputs';document.getElementById('pilotCost').textContent='Yield must be above 0 and no more than 100%.';return}const unit=(v.hours*v.rate+v.api)/(v.yield/100);document.getElementById('unitCost').textContent=unit.toLocaleString('en-US',{style:'currency',currency:'USD'});document.getElementById('pilotCost').textContent='30 accepted families: '+(30*unit).toLocaleString('en-US',{style:'currency',currency:'USD'});}for(const k of ['hours','rate','api','yield'])document.getElementById(k).addEventListener('input',cost);cost();</script></body></html>'''
(ROOT/'site/index.html').write_text(HTML.replace('__TAXONOMY__',rows).replace('__TRACES__',trace_links))
